<?php $title='Add Product';require 'includes/header.php';$cats=$pdo->query("SELECT * FROM categories ORDER BY name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$spec=[];foreach(($_POST['spec_key']??[]) as $i=>$k){if(trim($k)!=='')$spec[trim($k)]=trim($_POST['spec_val'][$i]??'');}$pdo->prepare("INSERT INTO products(category_id,product_name,short_description,description,price,discount_price,image,warranty,specifications,featured,active) VALUES(?,?,?,?,?,?,?,?,?,?,1)")->execute([(int)$_POST['category_id'],trim($_POST['product_name']),trim($_POST['short_description']),trim($_POST['description']),$_POST['price']?:null,$_POST['discount_price']?:null,trim($_POST['image']),trim($_POST['warranty']),json_encode($spec),isset($_POST['featured'])?1:0]);header('Location: products.php');exit;}?><h1>Add Product</h1><form method="post" class="card border-0 shadow-sm p-4 mt-3"><div class="row g-3"><div class="col-md-6"><label>Product Name</label><input required name="product_name" class="form-control"></div><div class="col-md-6"><label>Category</label><select required name="category_id" class="form-select"><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-12"><label>Short Description</label><input name="short_description" class="form-control"></div><div class="col-12"><label>Description</label><textarea name="description" rows="5" class="form-control"></textarea></div><div class="col-md-4"><label>Price</label><input type="number" step=".01" name="price" class="form-control"></div><div class="col-md-4"><label>Discount Price</label><input type="number" step=".01" name="discount_price" class="form-control"></div><div class="col-md-4"><label>Image URL</label><input name="image" class="form-control"></div><div class="col-md-6"><label>Warranty</label><input name="warranty" class="form-control"></div><div class="col-12"><label>Specifications</label><div id="specs"><div class="row g-2 mb-2"><div class="col-5"><input name="spec_key[]" class="form-control" placeholder="Capacity"></div><div class="col-5"><input name="spec_val[]" class="form-control" placeholder="150Ah"></div></div></div><button type="button" class="btn btn-sm btn-outline-secondary" onclick="addSpec()">Add Specification</button></div><div class="col-12"><label><input type="checkbox" name="featured"> Featured product</label></div><div class="col-12"><button class="btn btn-primary">Save Product</button></div></div></form><script>function addSpec(){document.getElementById('specs').insertAdjacentHTML('beforeend','<div class="row g-2 mb-2"><div class="col-5"><input name="spec_key[]" class="form-control"></div><div class="col-5"><input name="spec_val[]" class="form-control"></div></div>')}</script><?php require 'includes/footer.php';?>